<?php
/** Tenant-scoped personal setup. This session never grants PBX administrator permissions. */
require_once dirname(__DIR__,2).'/resources/require.php';
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');
header("Content-Security-Policy: default-src 'none'; style-src 'self' 'unsafe-inline'; img-src data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
$db=database::new()->db;$mobile=new pbx_mobile($db);$domain=pbx_tenant_domains::requestDomain($db);$error='';$notice='';$account=null;
if(!isset($_SESSION['openweb_phone_csrf']))$_SESSION['openweb_phone_csrf']=bin2hex(random_bytes(32));
try {
    if(($_SERVER['HTTPS']??'')!=='on'&&($_SERVER['HTTPS']??'')!=='1')throw new RuntimeException('Use your secure company address.');
    if($domain==='')throw new RuntimeException('Open your company’s OpenWeb PBX address to sign in. Ask your administrator for that address.');
    $saved=$_SESSION['openweb_phone_portal']??null;
    if(is_array($saved)&&($saved['domain_uuid']??'')===$domain&&($saved['expires_at']??0)>time())try{$account=$mobile->portalAccount($domain,$saved['extension_uuid'],(int)$saved['generation']);}catch(Throwable){unset($_SESSION['openweb_phone_portal']);}
    if(($_SERVER['REQUEST_METHOD']??'')==='POST') {
        if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['openweb_phone_csrf'],$_POST['csrf']))throw new DomainException('Your form expired. Refresh this page.');
        $action=$_POST['action']??'';
        if($action==='login') {
            $account=$mobile->passwordPrincipal($_POST,(string)($_SERVER['REMOTE_ADDR']??''),$_SERVER);
            session_regenerate_id(true);$_SESSION['openweb_phone_csrf']=bin2hex(random_bytes(32));
            $_SESSION['openweb_phone_portal']=['domain_uuid'=>$domain,'extension_uuid'=>$account['extension_uuid'],'generation'=>$account['password_generation'],'expires_at'=>time()+3600];
        } elseif($action==='logout') {
            unset($_SESSION['openweb_phone_portal']);$account=null;$_SESSION['openweb_phone_csrf']=bin2hex(random_bytes(32));$notice='You have signed out.';
        } else {
            if(!$account)throw new UnexpectedValueException('Sign in to manage your own phone.');
            if($action==='password') {
                $result=$mobile->changePassword($account,$_POST);$_SESSION['openweb_phone_portal']['generation']=$result['password_generation'];unset($_SESSION['openweb_phone_portal']['code']);
                $notice='App password changed. Other devices need to sign in again for future connections. An active call can finish.'.($result['connection_cleanup_pending']?' Registration cleanup is pending.':'');
            } elseif($action==='code')$_SESSION['openweb_phone_portal']['code']=$mobile->personalCode($account);
            elseif($action==='export') {
                $code=$_SESSION['openweb_phone_portal']['code']??null;
                if(!$code||strtotime($code['expires_at'])<=time())throw new RuntimeException('Create a new setup code first.');
                header('Content-Type: application/vnd.openwebpbx.config+json');header('Content-Disposition: attachment; filename="OpenWebPBX-'.$account['number'].'.openwebpbx"');echo $code['payload'];exit;
            } else throw new InvalidArgumentException('Choose an action.');
        }
    }
} catch(DomainException $ex){http_response_code(403);$error=$ex->getMessage();}catch(OverflowException $ex){http_response_code(429);$error=$ex->getMessage();}catch(UnexpectedValueException $ex){http_response_code(401);$error=$ex->getMessage();}catch(InvalidArgumentException $ex){http_response_code(400);$error=$ex->getMessage();}catch(Throwable){http_response_code(503);$error=$domain===''?'Use your company’s OpenWeb PBX address. Ask your administrator for that address.':'This request is unavailable. Try again or contact your administrator.';}
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$csrf=static function()use($e){echo '<input type="hidden" name="csrf" value="'.$e($_SESSION['openweb_phone_csrf']).'">';};
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My Phone · OpenWeb PBX</title><style>body{font:16px system-ui;background:#eef3fa;color:#142138;margin:0;padding:24px}main{overflow-wrap:anywhere;max-width:700px;margin:2em auto}section{background:white;border-radius:16px;padding:24px;margin:18px 0;box-shadow:0 5px 20px #19335912}h1{font-size:30px}label{display:block;margin:14px 0}input{display:block;box-sizing:border-box;width:100%;padding:12px;border:1px solid #8191a8;border-radius:7px;font:inherit}button,a.button{display:inline-block;background:#175fbe;color:white;border:0;border-radius:7px;padding:12px 18px;font:inherit;text-decoration:none;cursor:pointer}a{color:#1159b3}img{width:325px;max-width:100%;height:auto}.error{color:#a31525}.notice{color:#174c32}small{display:block;margin:12px 0}</style></head><body><main><h1>My Phone</h1><p>OpenWebPBX Free Phone</p><?php if($error): ?><section role="alert" class="error"><?= $e($error) ?></section><?php endif;if($notice): ?><section role="status" class="notice"><?= $e($notice) ?></section><?php endif;if($domain!==''&&!$account): ?><section><h2>Sign in</h2><form method="post"><?php $csrf(); ?><input type="hidden" name="action" value="login"><label>Extension<input name="extension" inputmode="numeric" pattern="[0-9]{2,10}" autocomplete="username" required maxlength="10"></label><label>App password<input type="password" name="password" autocomplete="current-password" required minlength="12" maxlength="128"></label><button>Sign in</button></form><p>Use the app password your administrator set for you. Ask them to reset it if you need help.</p></section><?php elseif($account): ?><section><h2><?= $e($account['user']['name']) ?></h2><p>Extension <strong><?= $e($account['number']) ?></strong></p><p><?= $e(pbx_tenant_domains::url($db,$domain)) ?></p><form method="post"><?php $csrf(); ?><button name="action" value="logout">Sign out</button></form></section><section><h2>Connect your app</h2><p>Install <a href="https://openwebpbx.com/#downloads">OpenWebPBX Free Phone</a>, then scan a QR code or open your private setup file.</p><form method="post"><?php $csrf(); ?><button name="action" value="code">Create setup code</button></form><?php $code=$_SESSION['openweb_phone_portal']['code']??null;if($code&&strtotime($code['expires_at'])>time()): ?><p><img alt="Private one-use phone setup QR code" src="data:image/png;base64,<?= base64_encode(pbx_mobile::qrPng($code['payload'])) ?>"></p><form method="post"><?php $csrf(); ?><button name="action" value="export">Download setup file</button></form><p>This code works once and expires in ten minutes. Keep it private. A new code replaces earlier unused invitations.</p><?php endif; ?></section><section><h2>Change app password</h2><form method="post"><?php $csrf(); ?><input type="hidden" name="action" value="password"><label>Current app password<input name="current_password" type="password" autocomplete="current-password" required maxlength="128"></label><label>New app password<input name="new_password" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><button>Change password</button><p>Use 12–128 characters. This does not change your SIP phone password. Other devices will need to sign in again for future connections; active calls can finish.</p></form></section><?php endif; ?><p><a href="https://openwebpbx.com/delete">Request account or data deletion</a> · <a href="https://openwebpbx.com/privacy">Privacy</a></p></main></body></html>
